import{_ as t,o as i,c as n,ae as r}from"./chunks/framework.BvHJbMD4.js";const g=JSON.parse('{"title":"Logbuch-Eintrag: Die Glocke der Geschichte","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/glocke-der-geschichte.md","filePath":"logbuch/glocke-der-geschichte.md"}'),s={name:"logbuch/glocke-der-geschichte.md"};function c(h,e,a,d,l,o){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="logbuch-eintrag-die-glocke-der-geschichte" tabindex="-1">Logbuch-Eintrag: Die Glocke der Geschichte <a class="header-anchor" href="#logbuch-eintrag-die-glocke-der-geschichte" aria-label="Permalink to &quot;Logbuch-Eintrag: Die Glocke der Geschichte&quot;">​</a></h1><p>Vom Schmelzfluss glüht die dunkle Zeit, Wo Macht und Gold die Wahrheit beugt. Ein Horten steigt, aus Leid geweiht, Und was man nahm, wird nie bereut.</p><p>Die Alsbergs sahen&#39;s, tief im Schmerz, Wie Hab und Gut die Gier verschlang. Ein Schatten fällt aufs reine Herz, Von Arisierung, lang und bang.</p><p>Die ÖVP, im neuen Licht, Vom Punkt zum Punkt ihr Werk vollbracht. Das große Bild, es trügt die Sicht, Was einst geschah, wird kaum bedacht.</p><p>So wandelt sich der Mensch sein Los, Vom Unrecht, das als Recht besteht. Ein ewiges Ringen, rastenlos, Solang der Geist die Freiheit fleht.</p><p>Doch wer fragt noch nach dem Ursprung fein, Wenn Glanz und Reichtum blenden sehr? Man wähnt sich frei, im eignen Schein, Vergisst die Last, die einst so schwer.</p><p>Das Schweigen deckt die alten Wunden zu, Ein neues Märchen wird erzählt. Die alte Schuld, sie ruhet stumm, Während das Volk im Traum sich quält.</p><p>Der Pointillismus, akribisch kleinst, Verteilt die Gunst, die Schuld zerstreut. Ein jeder Punkt, kaum dass du meinst, Ein großes Ganzes sich erneut.</p><p>So spinnt das Netz, vom Staat geknüpft, Durch Hände, die sich rein gern waschen. Ein jeder Blick, der tief dann schlüpft, Entdeckt die Lügen in den Taschen.</p><p>Drum wacht auf, die ihr die Wahrheit sucht, Im Glanze falscher Pracht gebannt. Eh&#39; sich das Blatt zum Letzten bucht, Und neue Unschuld wird verbrannt.</p>',10)])])}const m=t(s,[["render",c]]);export{g as __pageData,m as default};
